import {addToList,csvList,diagramPage,escapeHTML,formatOE,norm,partKey,safeURL,searchParts,validateImport,videoSpec} from './core.mjs';
import {GROUPS,META,MODELS,PARTS,SOURCES} from './data.mjs';
import {assemblySVG,carThumb,overviewSVG,smallIcon} from './draw.mjs';
import {BASE_VEHICLES,cleanVehicleProfiles,cleanVehicleSelection,vehicleById} from './vehicle-core.mjs';
import {VEHICLE_VARIANTS} from './vehicle-data.mjs';
import {createVehiclePicker} from './vehicle-ui.mjs';
import {addCatalogItem,catalogItemKey,cleanCatalogList} from './catalog-core.mjs';
import {BMW_CATALOG} from './catalog-data.mjs';
import {createCatalogExplorer} from './catalog-ui.mjs';
import {createWorkshopFAQ} from './workshop-ui.mjs';
let catalogExplorer;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],E=escapeHTML,STORE='coldstart-atlas-v1';
let stored={},storageOK=true;
try{stored=JSON.parse(localStorage.getItem(STORE)||'{}');}catch{storageOK=false;}
let imported={schemaVersion:1,parts:[],sources:[]};
try{if(stored.catalog)imported=validateImport(stored.catalog);}catch{stored.catalog=null;}
let parts=mergeParts(PARTS,imported.parts),sources=mergeSources(SOURCES,imported.sources);
function mergeParts(base,extra){return[...new Map([...base,...extra].map(p=>[partKey(p.model,p.id),p])).values()];}
function mergeSources(base,extra){return[...new Map([...base,...extra].map(s=>[s.id,s])).values()];}
const state={model:['E36','E46'].includes(stored.model)?stored.model:'E36',group:GROUPS.some(g=>g.id===stored.group)?stored.group:'front',selected:stored.selected??'front-disc',view:stored.model==='E46'?'exploded':'manual',manualFigure:null,tab:'part',zoom:1,explode:100,query:'',onlyNumbers:false,list:Array.isArray(stored.list)?stored.list.filter(x=>x&&['E36','E46'].includes(x.model)&&typeof x.id==='string').map(x=>({...x,qty:Math.max(1,Math.min(99,Math.floor(Number(x.qty)||1))),key:partKey(x.model,x.id),checked:x.checked===true,note:String(x.note??'').slice(0,1000)})):[],profiles:stored.profiles??{},videos:stored.videos??{},guides:stored.guides??{},diagrams:stored.diagrams??{},checks:stored.checks??{}};
try{state.catalogList=cleanCatalogList(stored.catalogList??[]);}catch{state.catalogList=[];}
state.catalogVariants=cleanVehicleSelection(VEHICLE_VARIANTS,stored.catalogVariants);
try{state.vehicleProfiles=cleanVehicleProfiles(VEHICLE_VARIANTS,stored.vehicleProfiles??{});}catch{state.vehicleProfiles={};}
const profileForVehicle=()=>state.catalogVariants[state.model]===BASE_VEHICLES[state.model]?(state.profiles[state.model]??{}):(state.vehicleProfiles[`${state.model}:${state.catalogVariants[state.model]}`]??{});
function saveVehicleProfile(profile){if(state.catalogVariants[state.model]===BASE_VEHICLES[state.model])state.profiles[state.model]=profile;else state.vehicleProfiles[`${state.model}:${state.catalogVariants[state.model]}`]=profile;}
const currentVehicle=()=>vehicleById(VEHICLE_VARIANTS,state.model,state.catalogVariants[state.model]);
const group=()=>GROUPS.find(g=>g.id===state.group),groupParts=()=>parts.filter(p=>p.model===state.model&&p.group===state.group),selectedPart=()=>parts.find(p=>p.id===state.selected&&p.model===state.model&&p.group===state.group),sourceFor=p=>sources.find(s=>s.id===p?.sourceId),gKey=()=>`${state.model}:${state.group}`;
let toastTimer=null,tempDiagram=null,diagramEditPart=null;
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3600);}
function save(){const payload={model:state.model,group:state.group,selected:state.selected,list:state.list,profiles:state.profiles,vehicleProfiles:state.vehicleProfiles,catalogVariants:state.catalogVariants,catalogList:state.catalogList,videos:state.videos,guides:state.guides,diagrams:state.diagrams,checks:state.checks,catalog:imported};try{localStorage.setItem(STORE,JSON.stringify(payload));if(!storageOK){storageOK=true;$('#storage-warning')?.remove();}}catch{storageOK=false;if(!$('#storage-warning')){const div=document.createElement('div');div.id='storage-warning';div.className='local-storage-warning';div.textContent='Lokales Speichern ist blockiert oder voll. Änderungen bleiben nur für diese Sitzung erhalten. Bitte die vollständige Sicherung unter „Daten & eigene Inhalte“ exportieren.';$('.app-shell').prepend(div);}notify('Speichern nicht möglich. Bitte Sicherung exportieren.');}}
function download(name,text,type='application/json'){const blob=new Blob([text],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),3000);}
function switchModel(model){if(!MODELS[model])return;catalogExplorer.active=true;state.model=model;state.view=model==='E36'?'manual':'exploded';state.manualFigure=null;state.selected=groupParts()[0]?.id??null;state.query='';state.tab='part';state.zoom=1;$('#search').value='';render();save();notify(`${model} gewählt. Passung bleibt offen; Projektlisten sind nach Baureihe getrennt.`);}
function switchGroup(id){if(!GROUPS.some(g=>g.id===id))return;catalogExplorer.active=false;catalogExplorer.sync();state.group=id;state.selected=groupParts()[0]?.id??null;state.view=state.model==='E36'&&!state.diagrams[gKey()]?'manual':'exploded';state.manualFigure=null;state.zoom=1;state.query='';state.tab='part';$('#search').value='';render();save();}
function choosePart(id,{scroll=false}={}){catalogExplorer.active=false;catalogExplorer.sync();const p=parts.find(p=>p.model===state.model&&p.id===id);if(!p)return;const keepManual=state.view==='manual'&&state.model==='E36'&&state.group===p.group;state.group=p.group;state.selected=p.id;state.view=keepManual?'manual':'exploded';if(keepManual){const f=figureForPart(p);if(f)state.manualFigure=f.id;}state.tab='part';state.query='';$('#search').value='';render();save();if(scroll&&matchMedia('(max-width:650px)').matches)$('#detail').scrollIntoView({behavior:'smooth',block:'start'});}
function render(){catalogExplorer?.sync();renderSidebar();renderHeader();renderSearch();if(catalogExplorer?.active)catalogExplorer.render();else{renderDrawing();renderTable();renderDetail();}}
function renderSidebar(){
 $$('.model-switch button').forEach(b=>{b.classList.toggle('active',b.dataset.model===state.model);b.setAttribute('aria-pressed',String(b.dataset.model===state.model));});
 $('#vehicle-thumb').innerHTML=carThumb(state.model);$('#vehicle-name').textContent=`BMW ${state.model} / ${state.catalogVariants[state.model]}`;$('#vehicle-profile').textContent=currentVehicle()?`${currentVehicle().label.replace(/^BMW /,'')} · ${currentVehicle().engine} · ${currentVehicle().id}`:MODELS[state.model].profile;
 catalogExplorer?.renderSidebar();
 $('#list-count').textContent=[...state.list,...state.catalogList].reduce((a,x)=>a+x.qty,0);
}
function renderHeader(){const m=MODELS[state.model],pr=profileForVehicle();$('#context-model').textContent=`${state.model} · ${currentVehicle()?.label??m.profile} · ${currentVehicle()?.engine??''} · ${state.catalogVariants[state.model]}`;$('#context-extra').textContent=pr.date?`Bauzeit ${pr.date}${pr.engine?' · '+pr.engine:''}`:'Bauzustand nicht erfasst';$('#breadcrumb').innerHTML=`${state.model} <span> / </span> ${E(group().family)} <span> / </span> <strong>${state.view==='car'?'Übersicht':group().code}</strong>`;$('#group-code').textContent=state.view==='car'?`${state.model} / 4 INTERAKTIVE BEREICHE`:`${group().code} / ${group().family.toUpperCase()}`;$('#drawing-title').textContent=state.view==='car'?'Dein Fahrzeug im Überblick':group().name;$('#view-exploded').setAttribute('aria-pressed',String(state.view==='exploded'));$('#view-car').setAttribute('aria-pressed',String(state.view==='car'));$('#view-manual').hidden=state.model!=='E36';$('#view-manual').setAttribute('aria-pressed',String(state.view==='manual'));$('#explode-label').hidden=state.view!=='exploded'||Boolean(state.diagrams[gKey()]);}
function renderDrawing(){const custom=state.diagrams[gKey()],page=diagramPage(groupParts(),state.selected);$('#diagram-pages').hidden=state.view==='car'||Boolean(custom)||page.pages<=1||state.view==='manual';$('#diagram-pages').innerHTML=`<button id="diagram-prev" aria-label="Vorherige Bauteilseite" ${page.page===0?'disabled':''}>←</button> ${page.page+1} / ${page.pages} <button id="diagram-next" aria-label="Nächste Bauteilseite" ${page.page>=page.pages-1?'disabled':''}>→</button>`;$('#diagram-count').textContent=state.view==='car'?'4 BEREICHE':`${groupParts().length} BAUTEILE${!custom&&page.pages>1?' / SEITE '+(page.page+1):''}`;$('#drawing').style.transform=`scale(${state.zoom})`;$('#zoom-label').textContent=`${Math.round(state.zoom*100)}%`;
 $('#drawing').classList.toggle('manual-mode',state.view==='manual');$('#manual-drawing-tools').hidden=state.view!=='manual';if(state.view==='manual'){const f=currentManualFigure();if(f){state.manualFigure=f.id;$('#drawing').innerHTML=manualDiagramHTML(f);$('#diagram-count').textContent=f.pins.length+' HANDBUCHPOSITIONEN';$('#manual-drawing-tools').innerHTML=`<select id="manual-figure-choice" aria-label="Handbuchabbildung wählen">${figuresForGroup(state.model,state.group).map(x=>`<option value="${x.id}" ${x.id===f.id?'selected':''}>${E(x.title)}</option>`).join('')}</select><button id="manual-enlarge">Vergrößern ↗</button>`;}}else if(state.view==='car')$('#drawing').innerHTML=overviewSVG(state.model);
 else if(custom&&isImage(custom.image)){
 const pins=groupParts().map((p,i)=>{const pin=custom.pins?.[p.id];return pin?`<button class="hotspot-pin" data-part="${E(p.id)}" style="left:${clamp(pin.x,0,100)}%;top:${clamp(pin.y,0,100)}%;${state.selected===p.id?'outline:3px solid white;':''}" aria-label="Position ${i+1}: ${E(p.name)}">${i+1}</button>`:'';}).join('');
 $('#drawing').innerHTML=`<div class="drawing-photo" style="aspect-ratio:${Number(custom.width)||800}/${Number(custom.height)||450};height:auto;width:90%"><img src="${E(custom.image)}" alt="${E(custom.title||'Eigene Baugruppenzeichnung')}">${pins}</div>`;
 }else $('#drawing').innerHTML=assemblySVG(page.parts,state.group,state.selected,state.explode,page.offset);
 $('.drawing-note').textContent=state.view==='manual'?`BENTLEY · US-AUSGABE 1999 · PDF ${currentManualFigure()?.pdfPage} / BUCH ${currentManualFigure()?.bookPage} · KEIN TEILEMATCH`:custom&&state.view!=='car'?`EIGENES BILD · ${custom.rights?'RECHTE VOM NUTZER BESTÄTIGT':'RECHTE OFFEN'} · QUELLE IN DATENANSICHT`:'EIGENE SCHEMATISCHE ZEICHNUNG · KEINE MONTAGEVORLAGE';
}
function renderTable(){const all=groupParts(),visible=all.filter(p=>!state.onlyNumbers||p.number);$('#parts-count').textContent=all.length;$('#parts-body').innerHTML=visible.length?visible.map(p=>`<tr class="part-row ${state.selected===p.id?'selected':''}" data-part="${E(p.id)}"><td>${String(all.indexOf(p)+1).padStart(2,'0')}</td><td><button class="row-name" data-part="${E(p.id)}">${E(p.name)}</button></td><td><code>${E(formatOE(p.number)||'Noch offen')}</code></td><td><span class="row-status ${p.number?'':'open'}">${p.number?'Referenz belegt':'Daten fehlen'}</span></td><td class="row-arrow">↗</td></tr>`).join(''):'<tr><td colspan="5">Für diese Baugruppe ist noch keine Referenznummer hinterlegt.</td></tr>';}
function renderSearch(){const box=$('#search-results');$('#clear-search').hidden=!state.query;box.hidden=!state.query;if(!state.query)return;const hits=searchParts(parts,state.model,state.query);box.innerHTML=`<div class="search-summary">${hits.length} Treffer in ${state.model}${hits.length>20?' · erste 20 angezeigt':''}</div>`+hits.slice(0,20).map(p=>`<button class="result-button" data-part="${E(p.id)}"><span>${E(p.name)}<small>${E(GROUPS.find(g=>g.id===p.group)?.name??p.group)}</small></span><code>${E(formatOE(p.number)||'Referenz offen')} ↗</code></button>`).join('')+(!hits.length?'<p class="search-summary">Andere Schreibweise oder Referenznummer versuchen. Der Startkatalog ist noch unvollständig.</p>':'');}
function renderDetail(){const p=selectedPart(),el=$('#detail');if(state.view==='car'||!p){el.innerHTML=`<div class="detail-empty"><div class="empty-icon">⌖</div><div class="eyebrow" style="margin-top:20px;color:#607d8c">VOM FAHRZEUG ZUM BAUTEIL</div><h2>Ein guter Überblick.<br>Ein klarer nächster Schritt.</h2><p>Wähle einen markierten Fahrzeugbereich oder eine Baugruppe links. Danach kannst du einzelne Teile und ihre Quellen aufrufen.</p><hr class="detail-divider"><p>Diese Fassung enthält vier ausgewählte Baugruppen je Baureihe. Weitere Komponenten und vollständige OEM-Zeichnungen benötigen passende Daten und Nutzungsrechte.</p><button class="primary full" data-action="coverage">Datenumfang ansehen ↗</button></div>`;return;}
 const src=sourceFor(p);el.innerHTML=`<div class="detail-top"><button class="back-drawing" data-action="back-drawing">← Zur Zeichnung</button><div class="eyebrow">${state.model} / POS. ${String(groupParts().indexOf(p)+1).padStart(2,'0')}</div><h2>${E(p.name)}</h2><p class="sub">${E(group().name)} · Referenzprofil ${MODELS[state.model].code}</p><span class="detail-badge ${p.number?'':'pending'}">${p.number?'✓ Referenz belegt · Passung offen':'○ Referenz noch nicht hinterlegt'}</span></div><div class="detail-tabs" role="tablist" aria-label="Bauteilinformationen"><button role="tab" id="tab-part" data-tab="part" class="${state.tab==='part'?'active':''}" aria-selected="${state.tab==='part'}" aria-controls="detail-content">Bauteil</button><button role="tab" id="tab-service" data-tab="service" class="${state.tab==='service'?'active':''}" aria-selected="${state.tab==='service'}" aria-controls="detail-content">Service</button><button role="tab" id="tab-video" data-tab="video" class="${state.tab==='video'?'active':''}" aria-selected="${state.tab==='video'}" aria-controls="detail-content">Videos</button></div><div class="detail-body" id="detail-content" role="tabpanel" aria-labelledby="tab-${state.tab}">${state.tab==='part'?partDetails(p,src):state.tab==='service'?serviceDetails(p):videoDetails(p)}</div>`;
}
function partDetails(p,src){return `<div class="detail-label">BMW-REFERENZNUMMER</div><div class="oe-line"><div class="oe-number">${E(formatOE(p.number)||'Noch offen')}</div>${p.number?'<button class="copy-btn" data-action="copy" aria-label="Teilenummer kopieren">⧉</button>':''}</div><p class="reference-note">${E(p.note)}</p><div class="mini-warning"><strong>Vor Bestellung abgleichen</strong>VIN, Bauzeit, Ausstattung und Umbauten sind nicht geprüft. „Referenz belegt“ bestätigt die Fundstelle, nicht die Passung.</div><button class="primary full" data-action="add">＋ Zur Projektliste</button><hr class="detail-divider"><div class="detail-label">QUELLEN & REFERENZEN</div>${src?sourceCard(src):'<p>Keine eindeutige Einzelreferenz hinterlegt. Über eine passende Originalquelle ergänzen.</p>'}${state.model==='E46'&&p.id==='front-disc'?sourceCard(sources.find(s=>s.id==='e46-front')):''}${manualPartSources(p)}<button class="muted-link" data-action="guide-edit">Eigene Unterlage hinterlegen</button>`;}
function sourceCard(s){if(!s||!safeURL(s.url))return'';return `<a class="source-card" href="${E(safeURL(s.url))}" target="_blank" rel="noopener noreferrer"><span>${E(s.title)} ↗</span><small>Abruf ${E(s.accessed||'nicht dokumentiert')} · Externe Originalseite</small></a>`;}
function validGuide(g){return g&&g.rights===true&&g.reviewed===true&&g.reviewer&&g.date&&safeURL(g.url);}
function serviceDetails(p){const g=state.guides[partKey(p.model,p.id)],valid=validGuide(g);let body='';
 if(g){body=`<div class="guide-state">${valid?'Fachprüfung vom Nutzer dokumentiert':'Entwurf · fachlich nicht freigegeben'}</div><p><strong>${E(g.title)}</strong></p>${['Vorbereitung','Ausbau','Einbau','Service / Abschluss'].map((s,i)=>`<div class="step-item"><strong>${s}</strong><p style="white-space:pre-wrap">${E(g.steps?.[i]||'Keine Angaben hinterlegt.')}</p></div>`).join('')}<p style="margin-top:13px;font-size:9px">Quelle: ${E(g.url)}<br>Prüfung: ${E(g.reviewer||'offen')} · ${E(g.date||'Datum offen')}<br>Diese Metadaten wurden vom Nutzer eingetragen; COLDSTART hat die Fachprüfung nicht verifiziert.</p>`;
 }else if(topicsForPart(p).length){body=`<div class="guide-state">Handbuch-Fundstellen vorhanden · Fachprüfung offen</div><p>Die deutsche Arbeitsübersicht verweist auf genaue Originalstellen. US-Ausführung, Redaktionsstand und tatsächlichen Bauzustand abgleichen.</p>`;}else body=`<div class="guide-state">Fahrzeugspezifische Anleitung fehlt</div><p>Für dieses Bauteil ist noch keine lizenzierte und fachlich geprüfte Ausbau-/Einbauanleitung hinterlegt.</p><div class="step-item"><strong>01 / Vorbereitung</strong><p>Baureihe, Bauzustand und tatsächliches Bauteil anhand geeigneter Quellen abgleichen. Arbeitsumfang und Verantwortlichen festlegen.</p></div><div class="step-item"><strong>02 / Ausbau & Einbau</strong><p>Erst eine passende freigegebene Anleitung beschaffen. Das Schema zeigt weder Montagefolge noch Drehmomente oder Wiederverwendbarkeit.</p></div><div class="step-item"><strong>03 / Service & Abschluss</strong><p>Verwendete Teile, tatsächlich durchgeführte Arbeiten, fachgerechte Prüfungen und offene Punkte dokumentieren. Keine automatische Fahrzeugfreigabe.</p></div>`;
 return `${group().family==='Bremsanlage'?'<div class="mini-warning" style="margin-top:0"><strong>Bremsen sind sicherheitskritisch</strong>Diese Ansicht erteilt keine Reparaturfreigabe. Arbeiten und Abschlussprüfung benötigen passende Fachkenntnis, Ausrüstung und fahrzeuggültige Daten.</div>':''}${body}${learningContextHTML(p,'guide')}${manualServiceHTML(p)}${documentPartLinks(p)}${group().family==='Bremsanlage'?sourceCard(sources.find(s=>s.id==='brembo')):''}<button class="small-button full" style="margin-top:15px" data-action="guide-edit">${g?'Unterlage bearbeiten':'Eigene Anleitung hinterlegen'}</button><button class="muted-link" data-action="workcard">Arbeitskarte vorbereiten ↗</button>`;
}
function videoDetails(p){const key=partKey(p.model,p.id),videos=(Array.isArray(state.videos[key])?state.videos[key]:[]).filter(v=>videoSpec(v.url));return `${learningContextHTML(p,'video')}<div class="detail-label" style="margin-top:20px">MEINE EIGENEN VERKNÜPFUNGEN</div>${videos.length?videos.map((v,i)=>`<article class="video-card"><h3>${E(v.title)}</h3><p>${E(v.note||'Eigene Videoverknüpfung')}<br>${v.rights?'Nutzungsrecht vom Nutzer bestätigt':'Rechte nicht dokumentiert'}</p><button class="small-button" data-play="${i}">▶ Video laden</button><div id="video-slot-${i}"></div><button class="muted-link" data-remove-video="${i}">Verknüpfung entfernen</button></article>`).join(''):'<div class="video-empty"><div class="video-symbol">▷</div><p>Noch keine eigenen Videos hinterlegt. Ergänze ein eigenes MP4-/WebM-Video oder eine passende YouTube-Verknüpfung.</p><p style="font-size:9px;margin-top:10px">Externe Inhalte werden erst nach deinem Klick geladen. Ein Video ersetzt keine fahrzeugspezifische Freigabe.</p></div>'}<button class="small-button full" style="margin-top:16px" data-action="video-edit">＋ Video hinterlegen</button>`;}
function modal(title,html){$('#modal').classList.remove('manual-reader');$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal-body').scrollTop=0;$('#modal').scrollTop=0;}
function clamp(n,a,b){return Math.max(a,Math.min(b,Number(n)||0));}
function isImage(s){return typeof s==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s)&&s.length<3000000;}
function openProfile(){const p=profileForVehicle();modal('Bauzustand dokumentieren',`<p>Das Referenzprofil ist kein VIN-Decoder. Diese Angaben helfen dir beim Quellenabgleich; sie lösen keine automatische Teilezuordnung aus.</p><form id="profile-form"><div class="form-grid"><label>Bauzeit (Monat / Jahr)<input name="date" placeholder="z. B. 06/1998" maxlength="30" value="${E(p.date??'')}"></label><label>Tatsächlich verbauter Motor<input name="engine" maxlength="80" placeholder="aus verifizierter Quelle" value="${E(p.engine??'')}"></label><label class="wide">Bekannte Umbauten<textarea name="mods" maxlength="1000" style="width:100%;margin-top:8px;background:#0d1820;border:1px solid #3d5665;color:#e3eff5;padding:12px;border-radius:5px" rows="3">${E(p.mods??'')}</textarea></label></div><p style="font-size:10px">Keine VIN oder persönlichen Fahrzeugdaten erforderlich. Angaben bleiben in diesem Browser; eine Sicherung exportiert sie mit.</p><button class="primary" type="submit">Bauzustand speichern</button></form>`);}
function openProject(){modal('Meine Projektliste',`<p>Bauteile sammeln, Mengen selbst festlegen und die tatsächliche Passung prüfen. Die Liste bestellt nichts und bestätigt keine Kompatibilität.</p>${state.list.length?state.list.map((x,i)=>{const p=parts.find(p=>p.model===x.model&&p.id===x.id);return`<div class="project-item"><div><strong>${x.model} / ${E(p?.name??x.id)}</strong><small>${E(formatOE(p?.number)||'Referenz offen')}</small><label class="check-label"><input type="checkbox" data-list-check="${i}" ${x.checked?'checked':''}> Passung selbst fachlich abgeglichen</label><textarea data-list-note="${i}" aria-label="Notiz zu ${E(p?.name??x.id)}" placeholder="Quelle, offene Punkte oder nächste Aufgabe" maxlength="1000" rows="2">${E(x.note??'')}</textarea></div><label style="font-size:9px;color:#9cb6c4">MENGE<input class="qty" type="number" min="1" max="99" value="${x.qty}" data-list-qty="${i}" aria-label="Menge ${E(p?.name??x.id)}"></label><button class="remove-item" data-list-remove="${i}" aria-label="${E(p?.name??x.id)} aus Projektliste entfernen">×</button></div>`;}).join(''):state.catalogList.length?'':'<div class="empty-state">Noch keine Bauteile gesammelt. Wähle ein Teil und klicke „Zur Projektliste“.</div>'}${catalogProjectHTML()}<div class="dialog-actions"><button class="primary" id="csv-export" ${state.list.length||state.catalogList.length?'':'disabled'}>Liste als CSV exportieren</button><button class="secondary" data-action="workcard">Arbeitskarte drucken</button></div>`);}
function catalogProjectHTML(){return state.catalogList.map((x,i)=>`<div class="project-item catalog-project-row"><div><strong>${x.model} / ${E(x.name)}</strong>${x.variantId?`<small>${E(x.vehicleLabel)} · ${E(x.engine)} · ${E(x.variantId)}</small>`:''}<small>${E(formatOE(x.number)||x.number||'Referenz offen')} · Position ${E(x.position)} · ${E(x.componentName)}</small><a class="muted-link" href="${E(x.url)}" target="_blank" rel="noopener noreferrer">Originalquelle ↗</a><label class="check-label"><input type="checkbox" data-catalog-check="${i}" ${x.checked?'checked':''}> Passung selbst fachlich abgeglichen</label><textarea data-catalog-note="${i}" aria-label="Notiz zu ${E(x.name)}" placeholder="Quelle, offene Punkte oder nächste Aufgabe" maxlength="1000" rows="2">${E(x.userNote)}</textarea></div><label style="font-size:9px;color:#9cb6c4">MENGE<input class="qty" type="number" min="1" max="99" value="${x.qty}" data-catalog-qty="${i}" aria-label="Menge ${E(x.name)}"></label><button class="remove-item" data-catalog-remove="${i}" aria-label="${E(x.name)} aus Projektliste entfernen">×</button></div>`).join('');}
function projectListEntries(){return [...state.list,...state.catalogList.map(x=>({...x,id:catalogItemKey(x),note:x.userNote}))];}
function projectListParts(){return [...parts,...state.catalogList.map(x=>({...x,id:catalogItemKey(x),name:x.name+(x.variantId?` [${x.variantId} · ${x.engine}]`:'')}))];}
document.addEventListener('click',ev=>{const t=ev.target.closest('[data-catalog-remove]');if(!t)return;state.catalogList.splice(Number(t.dataset.catalogRemove),1);save();renderSidebar();openProject();});
document.addEventListener('input',ev=>{const t=ev.target;if(t.dataset.catalogQty!==undefined){const x=state.catalogList[Number(t.dataset.catalogQty)];if(x){x.qty=clamp(Math.floor(Number(t.value)||1),1,99);save();renderSidebar();}}if(t.dataset.catalogNote!==undefined){const x=state.catalogList[Number(t.dataset.catalogNote)];if(x){x.userNote=t.value;save();}}});
document.addEventListener('change',ev=>{const t=ev.target;if(t.dataset.catalogCheck!==undefined){const x=state.catalogList[Number(t.dataset.catalogCheck)];if(x){x.checked=t.checked;save();}}});
function openCoverage(){
 const profiles=Object.entries(BMW_CATALOG.profiles);
 modal('Datenumfang & Quellen',`<p>810 originale Typschlüssel sind auswählbar. Fahrzeugdaten und lokale Katalogabdeckung werden getrennt ausgewiesen. Erfasst am 30.10.2026 über die sichtbaren Leebmann24-Katalogseiten.</p><div class="metrics-grid">${profiles.map(([m,p])=>`<div class="metric"><b>${p.categories.reduce((n,c)=>n+c.groups.length,0)}</b><span>${m} · ${p.categories.length} Hauptgruppen</span></div>`).join('')}<div class="metric"><b>2</b><span>vollständige Referenzprofile</span></div></div><h3>Vollständige Referenzkataloge</h3><p>E36: 328i Coupé / M52 / BG11.<br>E46: 325i Limousine / M54 / AV31.<br>Bauzeit, Ausstattung und Umbauten werden nicht automatisch mit einer VIN abgeglichen. Andere Modelle und Karosserien sind nicht pauschal abgedeckt.</p><h3>Weitere Motorreferenzen</h3><p>Zusätzliche Motor-Bildtafeln sind für die in der Fahrzeugauswahl gekennzeichneten Typschlüssel importiert. Sie decken jeweils die Hauptgruppe Motor ab; die übrigen Hauptgruppen und weitere Ausführungen bleiben offen. Bei nicht importierten Ausführungen wird der Leebmann-Originalkatalog mit einer Typschlüssel-Anleitung angeboten.</p><h3>Zeichnungen und Positionen</h3><p>BMW-Originalgeometrie und Positionsnummern bleiben erhalten. Die COLDSTART-Ansicht ändert nur die Darstellung; „Originalansicht“ zeigt die ursprünglichen Farben. Mehrere Nummern an derselben Position bleiben getrennte Varianten. Die Menge stammt aus der Quelle und wird nicht als Bestellmenge übernommen.</p><div id="catalog-coverage-details" class="notice">Detailabdeckung wird geladen …</div><h3>Ausgeschlossene Bereiche</h3><p>Technische Literatur, Hilfs- und Betriebsstoffe / ColorSystem, Kompletträder Felgen und Reifen, Value Line Service und Reparatur sowie Individual-Ausstattung. Die separate Hauptgruppe „Räder“ bleibt enthalten.</p><h3>Werkstatt-FAQ</h3><p>14 recherchierte Themen mit Prüfwegen, mehreren Lösungsansätzen und 21 Hersteller- beziehungsweise Fachquellen. Bauteilhersteller-Anweisungen und dokumentierte Werkstatterfahrungen sind als solche gekennzeichnet; daraus werden keine pauschalen Ausfallquoten oder Wartungsintervalle abgeleitet.</p><button class="secondary" data-workshop-faq>Werkstatt-FAQ öffnen ↗</button><h3>Eigene Inhalte</h3><p>Deine bisherigen 83 Teileplätze, Handbuchbilder, Dokumente und Notizen bleiben über „Eigene Teile &amp; Handbuchbilder“ erreichbar. Persönliche Projektlisten bleiben in diesem Browser und sind in der JSON-Sicherung enthalten.</p><h3>Herkunft und Nutzung</h3><p>Zeichnungen: BMW / Leebmann24. Fahrzeugillustrationen: KI-generiert. Der Abruf ersetzt keine Datenlizenz für eine öffentliche oder kommerzielle Weiterverwertung. Diese Website bleibt mit ihrem bisherigen privaten Zugriff veröffentlicht.</p><a class="secondary" href="https://www.leebmann24.com/de/de/collection/bmw-ersatzteile-10004" target="_blank" rel="noopener noreferrer">Leebmann24-Originalkatalog ↗</a><h3>Vorhandene Unterlagen</h3><div class="dialog-actions"><button class="secondary" data-document-library>Dokumente &amp; Gutachten</button><button class="secondary" data-learning-library>Anleitungen &amp; Kaufquellen</button></div>`);
 fetch('catalog/coverage.json').then(r=>r.json()).then(c=>{const el=$('#catalog-coverage-details');if(el)el.innerHTML=Object.entries(c.profiles).map(([m,p])=>`<p>${m}: ${p.completeDetails} von ${p.uniqueDrawings} Teilelisten erfasst · ${p.positions} Positionen · ${p.variants} Varianten.${p.unavailableImages?` ${p.unavailableImages} Originalbild ist beim Anbieter nicht verfügbar.`:''}${p.unavailableDetails?` ${p.unavailableDetails} Einzelteilseiten waren nicht abrufbar; die Zeichnungen sind vorhanden.`:''}</p>`).join('');}).catch(()=>{const el=$('#catalog-coverage-details');if(el)el.textContent='Abdeckungsbericht konnte nicht geladen werden.';});
}
function openData(){modal('Daten & eigene Inhalte',`<p>Die private Website benötigt deinen ChatGPT-Zugang. Persönliche Ergänzungen bleiben im jeweiligen Browser; PC und Handy synchronisieren sie nicht automatisch. Ein Browserwechsel oder das Löschen von Websitedaten kann lokale Ergänzungen entfernen.</p><h3>1 / Eigene Teile ergänzen</h3><p>Der eingebaute Leebmann24-Katalog ist ein Quellenstand vom 30.10.2026. Ein eigenes JSON-Paket ergänzt weiterhin die vier bisherigen Ansichten unter „Eigene Teile &amp; Handbuchbilder“. Jede Nummer braucht eine Quelle. Ungültige Pakete werden vollständig abgewiesen.</p><div class="dialog-actions"><button class="primary" id="import-open">Daten / Sicherung importieren</button><button class="secondary" id="catalog-export">Eigene Teiledaten exportieren</button></div><h3>2 / Eigene Zeichnungen hinterlegen</h3><p>Für die bisherige eigene Ansicht <strong>${state.model} · ${E(group().name)}</strong> kannst du eine Rasterzeichnung hochladen und eigene Teilepositionen markieren. PNG, JPEG oder WebP, maximal 2 MB.</p><button class="file-button" id="diagram-open">＋ Eigene Zeichnung hochladen &amp; Hotspots setzen</button>${state.diagrams[gKey()]?'<button class="secondary" id="diagram-edit" style="margin-top:10px">Vorhandene eigene Zeichnung bearbeiten</button>':''}<h3>3 / Anleitungen und Videos</h3><p>In den bisherigen eigenen Teileansichten kannst du passende Unterlagen und Videos ergänzen. Eine Unterlage wird dadurch nicht fachlich geprüft. Dokumente und Handbücher bleiben zusätzlich über ihre eigenen Bereiche erreichbar.</p><h3>4 / Projekt sichern</h3><p>Die JSON-Sicherung enthält Bauzustand, beide Projektlisten, eigene Zeichnungen, Hotspots, Texte und Videoverknüpfungen. Original-PDFs und JPEGs der Dokumentenbibliothek sind nicht enthalten; diese separat aufbewahren. Die Sicherung wird als Datei heruntergeladen.</p><button class="primary" id="backup-export">Projekt-Sicherung exportieren</button><div class="notice">Version ${META.version} · Datenformat 1. Für eine lokale Kopie wird das vollständige Website-Paket benötigt. Die einzelne HTML-Datei enthält die neuen Katalogbilder und Teilelisten nicht. Externe Quellen und Videos benötigen eine Internetverbindung.</div>`);}

function openGuideEditor(){const p=selectedPart();if(!p)return;const g=state.guides[partKey(p.model,p.id)]??{};modal('Service-Unterlage hinterlegen',`<p>${state.model} / ${E(p.name)}. Hinterlege nur eigene oder rechtmäßig nutzbare Inhalte. Bei Bremsen und anderen kritischen Arbeiten sind fachlich passende Unterlagen und Prüfung nötig.</p><form id="guide-form"><label class="stacked-label">Titel<input name="title" required maxlength="160" value="${E(g.title??'')}" placeholder="z. B. eigene Service-Dokumentation"></label><label class="stacked-label">Quellennachweis (HTTPS)<input name="url" type="url" required value="${E(g.url??'')}" placeholder="https://…"></label>${['Vorbereitung','Ausbau','Einbau','Service / Abschluss'].map((label,i)=>`<label class="stacked-label">${label}<textarea name="step${i}" maxlength="8000" rows="4" placeholder="Quellengebundenen Text ergänzen; keine Werte schätzen.">${E(g.steps?.[i]??'')}</textarea></label>`).join('')}<div class="form-grid"><label>Fachlicher Prüfer<input name="reviewer" maxlength="100" value="${E(g.reviewer??'')}"></label><label>Prüfdatum<input type="date" name="date" value="${E(g.date??'')}"></label></div><label class="check-label"><input name="rights" type="checkbox" ${g.rights?'checked':''}> Ich verfüge über die erforderlichen Nutzungsrechte für diesen Inhalt.</label><label class="check-label"><input name="reviewed" type="checkbox" ${g.reviewed?'checked':''}> Fahrzeugbezug und Inhalt sind fachlich geprüft; Prüfer und Datum sind dokumentiert.</label><div id="form-error" class="error-text" role="alert"></div><button class="primary" type="submit">Unterlage lokal speichern</button></form>`);}
function openVideoEditor(){const p=selectedPart();if(!p)return;modal('Video am Bauteil hinterlegen',`<p>${state.model} / ${E(p.name)}. Eine Verknüpfung wird gespeichert; die Videodatei wird nicht kopiert oder hochgeladen.</p><form id="video-form"><label class="stacked-label">Videotitel<input name="title" required maxlength="160" placeholder="Titel der Anleitung"></label><label class="stacked-label">Video-URL<input name="url" type="url" required placeholder="https://www.youtube.com/watch?v=… oder https://…/video.mp4"></label><label class="stacked-label">Quellen-/Gültigkeitshinweis<textarea name="note" maxlength="1000" rows="3" placeholder="Bauzustand, Quelle und fachlichen Prüfstatus notieren"></textarea></label><label class="check-label"><input name="rights" type="checkbox" required> Ich darf dieses Video hier verknüpfen; die Verknüpfung bestätigt keine fachliche Richtigkeit.</label><div id="form-error" class="error-text" role="alert"></div><button class="primary" type="submit">Videoverknüpfung speichern</button></form><div class="notice">Unterstützt: YouTube, YouTube Shorts, direkte HTTPS-MP4-/WebM-Dateien. Bei „Video laden“ wird eine Verbindung zum Anbieter hergestellt. Keine automatischen Drittanbieter-Anfragen beim Öffnen der App.</div>`);}
function openHelp(){modal('Vom Fahrzeug zum Bauteil',`<ol><li><strong>E36 oder E46 wählen.</strong> Die Auswahl verwendet die getrennten Katalogprofile BG11 und AV31.</li><li><strong>Baugruppe öffnen.</strong> Klicke einen Bereich am Fahrzeug, einen Eintrag links oder eine Karte unter der Fahrzeugansicht.</li><li><strong>Zeichnung und Position wählen.</strong> Original-Positionsnummern verbinden Bild und Teileliste. Varianten bleiben getrennt und lassen sich einzeln zur Projektliste hinzufügen.</li></ol><h3>Zoom &amp; Verschieben</h3><p>Mausrad: Zoom am Mauszeiger. Ziehen: Ansicht verschieben. Touch: mit zwei Fingern zoomen, mit einem Finger verschieben. Doppelklick: vergrößern oder einpassen. Die Schaltflächen unten rechts bieten Zoom, Einpassen und Vollbild.</p><h3>Tastatur</h3><p><span class="shortcut">/</span> Suche · <span class="shortcut">Tab</span> Bedienelemente · <span class="shortcut">Enter</span> Auswahl. In der fokussierten Zeichnung: <span class="shortcut">+</span> / <span class="shortcut">−</span> Zoom, <span class="shortcut">0</span> Einpassen, Pfeiltasten Verschieben.</p><h3>Suche und Projektliste</h3><p>Die Suche findet Zeichnungsnamen und erfasste Bauteilnamen/Teilenummern. Nummern funktionieren mit und ohne Leerzeichen. Deine Projektliste speichert Mengen, Notizen und deinen eigenen Passungsabgleich browserlokal; CSV-Export und vollständige JSON-Sicherung enthalten auch die neuen Katalogpositionen.</p><h3>Vorhandene Inhalte</h3><p>Handbücher, Dokumente, Videos und eigene Ergänzungen bleiben erreichbar. Die bisherigen vier Ansichten liegen unter „Eigene Teile &amp; Handbuchbilder“.</p><button class="primary" data-action="coverage">Quellen und Datenumfang öffnen</button>`);}
function printWorkcard(){let block=$('#print-workcard');if(!block){block=document.createElement('section');block.id='print-workcard';block.className='print-only';document.body.append(block);}const pr=profileForVehicle(),list=projectListEntries().filter(x=>x.model===state.model&&(x.variantId?x.variantId===state.catalogVariants[state.model]:state.catalogVariants[state.model]===BASE_VEHICLES[state.model])),projectParts=projectListParts();block.innerHTML=`<h1>COLDSTART · Arbeitskarte</h1><p>${state.model} · ${E(currentVehicle()?.label??MODELS[state.model].profile)} · ${E(state.catalogVariants[state.model])}<br>Erstellt: ${new Date().toLocaleDateString('de-DE')}<br>Bauzeit: ${E(pr.date||'unbekannt')} · Motor: ${E(pr.engine||'nicht verifiziert')}<br>Umbauten: ${E(pr.mods||'nicht erfasst')}</p><p><strong>Planungsblatt, keine Arbeits- oder Fahrzeugfreigabe.</strong> Keine Drehmomente, Montagefolge oder fahrzeugspezifischen Sollwerte enthalten. Die eingetragene Menge ist vom Nutzer gewählt.</p><table><thead><tr><th>Bauteil</th><th>Referenz</th><th>Menge</th><th>Passung / offene Aufgabe</th></tr></thead><tbody>${list.length?list.map(x=>{const p=projectParts.find(p=>p.model===x.model&&p.id===x.id);return`<tr><td>${E(p?.name??x.id)}</td><td>${E(formatOE(p?.number)||'offen')}</td><td>${x.qty}</td><td>${x.checked?'Vom Nutzer bestätigt':'Offen'}<br>${E(x.note)}</td></tr>`;}).join(''):'<tr><td colspan="4">Keine Bauteile in der Projektliste dieser Baureihe.</td></tr>'}</tbody></table><p style="margin-top:20px">Beanstandung: ______________________________________________<br>Passende Reparaturquelle: _____________________________________<br>Verantwortliche Fachkraft: _____________________________________<br>Dokumentierte Abschlussprüfung / offene Punkte: __________________</p><small>Zeichnungen und Referenzen aus der App sind keine Montagevorlage. Eine korrekte Liste ersetzt weder geeignete Daten noch fachgerechte Prüfung.</small>`;$('#modal').close();window.print();}
function diagramEditor(){if(!tempDiagram)return;const ps=groupParts();diagramEditPart=diagramEditPart&&ps.some(p=>p.id===diagramEditPart)?diagramEditPart:ps[0]?.id;modal('Zeichnung & anklickbare Positionen',`<p>Wähle ein Bauteil und klicke seine Position im Bild an. Die Markierung ist eine von dir gesetzte Zuordnung, kein automatischer Teileabgleich.</p><label class="stacked-label">Bauteil für nächsten Hotspot<select id="pin-part">${ps.map(p=>`<option value="${E(p.id)}" ${p.id===diagramEditPart?'selected':''}>${E(p.name)}${tempDiagram.pins?.[p.id]?' · markiert':''}</option>`).join('')}</select></label><div class="custom-image-stage" id="pin-stage" style="height:auto;aspect-ratio:${tempDiagram.width}/${tempDiagram.height};cursor:crosshair"><img src="${E(tempDiagram.image)}" alt="Eigene Zeichnung zur Positionierung">${ps.map((p,i)=>{const pin=tempDiagram.pins?.[p.id];return pin?`<button class="hotspot-pin" style="left:${pin.x}%;top:${pin.y}%">${i+1}</button>`:'';}).join('')}</div><label class="stacked-label" style="margin-top:18px">Bildtitel<input id="image-title" maxlength="160" value="${E(tempDiagram.title??'Eigene Baugruppenzeichnung')}"></label><label class="stacked-label">Quelle / Lizenznachweis<input id="image-credit" maxlength="500" value="${E(tempDiagram.credit??'')}"></label><label class="check-label"><input id="image-rights" type="checkbox" ${tempDiagram.rights?'checked':''}> Ich habe die nötigen Rechte für dieses Bild und seine Nutzung.</label><p style="font-size:10px">${Object.keys(tempDiagram.pins??{}).length} von ${ps.length} Positionen markiert. Alle Bauteile bleiben auch ohne Markierung in der Teileliste erreichbar.</p><div id="form-error" class="error-text" role="alert"></div><div class="dialog-actions"><button class="primary" id="diagram-save">Zeichnung lokal speichern</button><button class="secondary" id="pin-remove">Markierung des gewählten Teils entfernen</button><button class="secondary" id="diagram-default">Schema wieder verwenden</button></div>`);}
function rememberDiagramFields(){if(!tempDiagram)return;tempDiagram.title=$('#image-title')?.value??tempDiagram.title;tempDiagram.credit=$('#image-credit')?.value??tempDiagram.credit;tempDiagram.rights=$('#image-rights')?.checked??tempDiagram.rights;}
async function importFile(file){if(!file)return;if(file.size>30*1024*1024){notify('Import abgelehnt: maximal 30 MB.');return;}try{const raw=JSON.parse(await file.text());const catalog=validateImport(raw);let backup=null;if(raw.type==='coldstart-backup'){backup=validateBackup(raw);}const next=mergeParts(parts,catalog.parts),nextSources=mergeSources(sources,catalog.sources);imported={schemaVersion:1,parts:mergeParts(imported.parts,catalog.parts),sources:mergeSources(imported.sources,catalog.sources)};parts=next;sources=nextSources;if(backup){for(const k of ['profiles','vehicleProfiles','list','catalogList','catalogVariants','videos','guides','diagrams'])state[k]=backup[k];}if(!selectedPart())state.selected=groupParts()[0]?.id;save();render();$('#modal').close();notify(`Import abgeschlossen: ${catalog.parts.length} Teile, ${catalog.sources.length} Quellen${backup?' und persönliche Sicherung':''}.`);}catch(err){notify(`Import unverändert abgewiesen: ${String(err.message).slice(0,200)}`);}}
function validateBackup(raw){const b={profiles:{},videos:{},guides:{},diagrams:{},list:[]};if(!raw.personal||typeof raw.personal!=='object')throw new Error('Sicherung enthält keine persönlichen Datenfelder.');const v=raw.personal;b.catalogList=cleanCatalogList(v.catalogList??[]);b.catalogVariants=cleanVehicleSelection(VEHICLE_VARIANTS,v.catalogVariants);b.vehicleProfiles=cleanVehicleProfiles(VEHICLE_VARIANTS,v.vehicleProfiles??{});
 for(const model of ['E36','E46']){const pr=v.profiles?.[model];if(pr&&typeof pr==='object')b.profiles[model]={date:String(pr.date??'').slice(0,30),engine:String(pr.engine??'').slice(0,80),mods:String(pr.mods??'').slice(0,1000)};}
 const keys=new Set(raw.parts.map(p=>partKey(p.model,p.id))),groupKeys=new Set(['E36','E46'].flatMap(m=>GROUPS.map(g=>`${m}:${g.id}`)));
 if(!Array.isArray(v.list)||v.list.length>5000)throw new Error('Projektliste in der Sicherung ist ungültig.');
 b.list=v.list.map(x=>{if(!keys.has(partKey(x.model,x.id)))throw new Error('Projektliste verweist auf ein unbekanntes Bauteil.');return{key:partKey(x.model,x.id),model:x.model,id:x.id,qty:clamp(Math.floor(Number(x.qty)||1),1,99),checked:x.checked===true,note:String(x.note??'').slice(0,1000)};});
 for(const [k,arr] of Object.entries(v.videos??{})){if(!keys.has(k)||!Array.isArray(arr)||arr.length>30)throw new Error('Videozuordnung ungültig.');b.videos[k]=arr.map(a=>{if(!videoSpec(a.url))throw new Error('Unzulässige Video-URL in Sicherung.');return{title:String(a.title??'Video').slice(0,160),url:videoSpec(a.url).url,note:String(a.note??'').slice(0,1000),rights:a.rights===true};});}
 for(const [k,g] of Object.entries(v.guides??{})){if(!keys.has(k)||!safeURL(g.url))throw new Error('Service-Quelle in Sicherung ungültig.');b.guides[k]={title:String(g.title??'').slice(0,160),url:safeURL(g.url),steps:[0,1,2,3].map(i=>String(g.steps?.[i]??'').slice(0,8000)),reviewer:String(g.reviewer??'').slice(0,100),date:String(g.date??'').slice(0,20),rights:g.rights===true,reviewed:g.reviewed===true};}
 for(const [k,d] of Object.entries(v.diagrams??{})){if(!groupKeys.has(k)||!isImage(d.image)||!Number.isFinite(d.width)||!Number.isFinite(d.height)||d.width<1||d.height<1)throw new Error('Zeichnung in der Sicherung ungültig.');const pins={};for(const [id,pin] of Object.entries(d.pins??{})){if(!keys.has(partKey(k.split(':')[0],id)))throw new Error('Hotspot verweist auf unbekanntes Teil.');pins[id]={x:clamp(pin.x,0,100),y:clamp(pin.y,0,100)};}b.diagrams[k]={image:d.image,width:d.width,height:d.height,title:String(d.title??'').slice(0,160),credit:String(d.credit??'').slice(0,500),rights:d.rights===true,pins};}return b;
}
function backupExport(){const data={schemaVersion:1,type:'coldstart-backup',createdAt:new Date().toISOString(),parts,sources,personal:{profiles:state.profiles,vehicleProfiles:state.vehicleProfiles,catalogVariants:state.catalogVariants,list:state.list,catalogList:state.catalogList,videos:state.videos,guides:state.guides,diagrams:state.diagrams}};download(`coldstart-atlas-sicherung-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(data,null,2));notify('Vollständige Sicherung exportiert. Bitte sicher aufbewahren.');}
async function copyNumber(){const p=selectedPart();if(!p?.number)return;try{await navigator.clipboard.writeText(p.number);notify('Referenznummer kopiert – Passung vor Bestellung prüfen.');}catch{modal('Referenznummer kopieren',`<p>Die Zwischenablage ist in diesem Browser nicht verfügbar. Die Nummer unten auswählen und kopieren.</p><label class="stacked-label">BMW-Referenznummer<input id="manual-copy" value="${p.number}" readonly></label>`);$('#manual-copy').select();}}
document.addEventListener('click',async ev=>{
 const t=ev.target.closest('button,a,[role="button"],tr[data-part]');if(!t)return;
 if(t.dataset.model){switchModel(t.dataset.model);return;}
 if(t.dataset.group){switchGroup(t.dataset.group);return;}
 if(t.dataset.part){if(t.dataset.keepManual){state.view='manual';state.manualFigure=t.dataset.keepManual;if($('#modal').open)$('#modal').close();}choosePart(t.dataset.part,{scroll:true});return;}
 if(t.dataset.tab){state.tab=t.dataset.tab;renderDetail();return;}
 const action=t.dataset.action;
 if(action==='add'){const p=selectedPart();state.list=addToList(state.list,p);save();renderSidebar();notify(`${p.name} zur ${p.model}-Projektliste hinzugefügt.`);return;}
 if(action==='copy'){await copyNumber();return;}if(action==='back-drawing'){$('#drawing-stage').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(action==='coverage'){openCoverage();return;}
 if(action==='guide-edit'){openGuideEditor();return;}
 if(action==='video-edit'){openVideoEditor();return;}
 if(action==='workcard'){printWorkcard();return;}
 if(t.dataset.play!==undefined){const p=selectedPart(),v=state.videos[partKey(p.model,p.id)]?.[Number(t.dataset.play)],spec=videoSpec(v?.url);if(!spec)return;const slot=$(`#video-slot-${t.dataset.play}`);slot.innerHTML=spec.type==='youtube'?`<iframe src="${E(spec.embed)}" title="${E(v.title)}" allow="fullscreen; picture-in-picture" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`:`<video controls preload="metadata" src="${E(spec.url)}" aria-label="${E(v.title)}"></video>`;t.disabled=true;t.textContent='Video geladen';return;}
 if(t.dataset.removeVideo!==undefined){const key=partKey(state.model,state.selected);state.videos[key].splice(Number(t.dataset.removeVideo),1);save();renderDetail();notify('Videoverknüpfung entfernt.');return;}
 if(t.dataset.listRemove!==undefined){state.list.splice(Number(t.dataset.listRemove),1);save();renderSidebar();openProject();return;}
 switch(t.id){case'help':openHelp();break;case'profile-open':openProfile();break;case'overview':case'view-car':catalogExplorer.showOverview();break;case'view-exploded':state.view='exploded';renderHeader();renderDrawing();renderDetail();break;case'project-open':openProject();break;case'data-open':openData();break;case'coverage-open':openCoverage();break;case'modal-close':$('#modal').close();break;case'diagram-prev':case'diagram-next':{const pg=diagramPage(groupParts(),state.selected),next=pg.page+(t.id==='diagram-next'?1:-1);choosePart(groupParts()[next*6]?.id);break;}case'zoom-in':state.zoom=Math.min(1.8,state.zoom+.2);renderDrawing();break;case'zoom-out':state.zoom=Math.max(.6,state.zoom-.2);renderDrawing();break;case'zoom-reset':state.zoom=1;state.explode=100;$('#explode').value=100;renderDrawing();break;case'clear-search':state.query='';$('#search').value='';renderSearch();$('#search').focus();break;case'export-project':case'csv-export':download(`coldstart-projektliste.csv`,csvList(projectListEntries(),projectListParts()),'text/csv;charset=utf-8');notify('Projektliste exportiert.');break;case'import-open':$('#import-file').click();break;case'catalog-export':download('coldstart-atlas-daten.json',JSON.stringify({schemaVersion:1,parts,sources},null,2));notify('Datenpaket exportiert.');break;case'backup-export':backupExport();break;case'diagram-open':$('#diagram-file').click();break;case'diagram-edit':tempDiagram=JSON.parse(JSON.stringify(state.diagrams[gKey()]));diagramEditor();break;case'pin-remove':rememberDiagramFields();delete tempDiagram.pins[diagramEditPart];diagramEditor();break;case'diagram-default':delete state.diagrams[gKey()];save();$('#modal').close();render();notify('Eigene Schemazeichnung wieder aktiv.');break;case'diagram-save':rememberDiagramFields();if(!tempDiagram.rights||!tempDiagram.credit){$('#form-error').textContent='Bitte Nutzungsrechte bestätigen und Quelle / Lizenznachweis dokumentieren.';break;}state.diagrams[gKey()]=JSON.parse(JSON.stringify(tempDiagram));save();$('#modal').close();render();notify('Eigene Zeichnung und Hotspots gespeichert.');break;}
});
document.addEventListener('input',ev=>{const t=ev.target;if(t.dataset.listQty!==undefined){const n=clamp(Math.floor(Number(t.value)||1),1,99);state.list[Number(t.dataset.listQty)].qty=n;save();renderSidebar();}if(t.id==='search'){state.query=t.value;renderSearch();}if(t.id==='explode'){state.explode=Number(t.value);renderDrawing();}if(t.dataset.listNote!==undefined){state.list[Number(t.dataset.listNote)].note=t.value;save();}});
document.addEventListener('change',async ev=>{const t=ev.target;if(t.id==='numbers-only'){state.onlyNumbers=t.checked;renderTable();}if(t.id==='pin-part'){rememberDiagramFields();diagramEditPart=t.value;}if(t.dataset.listQty!==undefined){const n=clamp(Math.floor(Number(t.value)||1),1,99);state.list[Number(t.dataset.listQty)].qty=n;t.value=n;save();renderSidebar();}if(t.dataset.listCheck!==undefined){state.list[Number(t.dataset.listCheck)].checked=t.checked;save();}if(t.id==='import-file'){await importFile(t.files[0]);t.value='';}if(t.id==='diagram-file'){const f=t.files[0];t.value='';if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>2000000){notify('Nur PNG, JPEG und WebP bis 2 MB sind zulässig.');return;}const reader=new FileReader();reader.onload=()=>{const img=new Image();img.onload=()=>{tempDiagram={image:reader.result,width:img.naturalWidth,height:img.naturalHeight,title:'Eigene Baugruppenzeichnung',credit:'',rights:false,pins:{}};diagramEditPart=null;diagramEditor();};img.onerror=()=>notify('Bild konnte nicht gelesen werden.');img.src=reader.result;};reader.readAsDataURL(f);}});
document.addEventListener('click',ev=>{const stage=ev.target.closest('#pin-stage');if(!stage||!tempDiagram||!diagramEditPart)return;rememberDiagramFields();const rect=stage.getBoundingClientRect();tempDiagram.pins[diagramEditPart]={x:Math.round(clamp((ev.clientX-rect.left)/rect.width*100,0,100)*100)/100,y:Math.round(clamp((ev.clientY-rect.top)/rect.height*100,0,100)*100)/100};diagramEditor();});
document.addEventListener('submit',ev=>{if(!['profile-form','guide-form','video-form'].includes(ev.target.id))return;ev.preventDefault();const fd=new FormData(ev.target),val=k=>String(fd.get(k)??'').trim();if(ev.target.id==='profile-form'){saveVehicleProfile({date:val('date'),engine:val('engine'),mods:val('mods')});save();renderHeader();$('#modal').close();notify('Bauzustand gespeichert. Die Passung bleibt offen.');}if(ev.target.id==='video-form'){const spec=videoSpec(val('url'));if(!spec){$('#form-error').textContent='Bitte eine gültige HTTPS-YouTube-URL oder einen direkten MP4-/WebM-Link eingeben.';return;}const key=partKey(state.model,state.selected);state.videos[key]??=[];if(state.videos[key].length>=30){$('#form-error').textContent='Maximal 30 Videoverknüpfungen pro Bauteil.';return;}state.videos[key].push({title:val('title'),url:spec.url,note:val('note'),rights:fd.has('rights')});save();state.tab='video';renderDetail();$('#modal').close();notify('Videoverknüpfung lokal gespeichert.');}if(ev.target.id==='guide-form'){if(!safeURL(val('url'))){$('#form-error').textContent='Bitte eine HTTPS-Quellenadresse ohne Zugangsdaten verwenden.';return;}if(fd.has('reviewed')&&(!val('reviewer')||!val('date'))){$('#form-error').textContent='Für dokumentierte Fachprüfung sind Prüfer und Datum erforderlich.';return;}state.guides[partKey(state.model,state.selected)]={title:val('title'),url:safeURL(val('url')),steps:[0,1,2,3].map(i=>val(`step${i}`)),reviewer:val('reviewer'),date:val('date'),rights:fd.has('rights'),reviewed:fd.has('reviewed')};save();state.tab='service';renderDetail();$('#modal').close();notify('Service-Unterlage gespeichert. Fachstatus ist getrennt ausgewiesen.');}});
document.addEventListener('keydown',ev=>{if(ev.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)&&!$('#modal').open){ev.preventDefault();if(catalogExplorer.active)catalogExplorer.focusSearch();else $('#search').focus();}if(['Enter',' '].includes(ev.key)&&ev.target.matches('g[role="button"]')){ev.preventDefault();ev.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(ev.target.matches('[role="tab"]')&&['ArrowLeft','ArrowRight'].includes(ev.key)){ev.preventDefault();const tabs=$$('.detail-tabs button'),i=tabs.indexOf(ev.target),n=tabs[(i+(ev.key==='ArrowRight'?1:2))%3];state.tab=n.dataset.tab;renderDetail();$(`#tab-${state.tab}`).focus();}});
$('#modal').addEventListener('click',ev=>{if(ev.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)$('#modal').close();}});
$('.brand').addEventListener('click',ev=>{ev.preventDefault();catalogExplorer.showOverview();});
catalogExplorer=createCatalogExplorer({model:()=>state.model,variant:()=>state.catalogVariants[state.model],legacy:switchGroup,notify,changed:renderSidebar,add:item=>{state.catalogList=addCatalogItem(state.catalogList,item);save();renderSidebar();notify(`${item.name} zur ${item.model}-Projektliste hinzugefügt.`);}});
createWorkshopFAQ({modal,model:()=>state.model});
createVehiclePicker({modal,model:()=>state.model,selected:()=>state.catalogVariants[state.model],choose:id=>{if(!vehicleById(VEHICLE_VARIANTS,state.model,id))return;state.catalogVariants[state.model]=id;catalogExplorer.active=true;render();save();notify(`${id} gewählt. Katalogumfang wird für diese Ausführung angezeigt.`);}});
if(!selectedPart())state.selected=groupParts()[0]?.id;render();if(!storageOK)save();initManuals().catch(()=>{});
